package ru.meguboom.mobile;
import org.json.*;import java.util.*;import java.text.Normalizer;
final class CollectionFolders {
 static boolean matches(String name){String n=Normalizer.normalize(name,Normalizer.Form.NFKC).toLowerCase(Locale.ROOT).replaceFirst("^\\s*\\d+[.)]\\s*","").replaceAll("[_-]+"," ").trim().replaceAll("\\s+"," ");return n.matches("^(?:ваха(?:\\s*40[кk])?|waha(?:\\s*40[кk])?|warhammer(?:\\s*40(?:[,. ]?000|[кk]))?|wh40k|40[кk](?:\\s+отсортировано)?)$");}
 static JSONArray select(JSONArray folders)throws JSONException{Map<String,JSONObject> all=new HashMap<>();Set<String> matched=new HashSet<>();for(int i=0;i<folders.length();i++){JSONObject f=folders.getJSONObject(i);all.put(f.getString("id"),f);if(matches(f.optString("name")))matched.add(f.getString("id"));}List<JSONObject> selected=new ArrayList<>();for(String id:matched){Set<String> visited=new HashSet<>();List<String> pending=new ArrayList<>();JSONObject item=all.get(id);JSONArray parents=item.optJSONArray("parents");if(parents!=null)for(int j=0;j<parents.length();j++)pending.add(parents.getString(j));boolean nested=false;while(!pending.isEmpty()){String parent=pending.remove(pending.size()-1);if(!visited.add(parent))continue;if(matched.contains(parent)){nested=true;break;}JSONObject f=all.get(parent);if(f==null)continue;JSONArray ps=f.optJSONArray("parents");if(ps!=null)for(int j=0;j<ps.length();j++)pending.add(ps.getString(j));}if(!nested){JSONObject copy=new JSONObject(item.toString());copy.put("label",copy.optString("name"));selected.add(copy);}}selected.sort((a,b)->Integer.compare(priority(a.optString("name")),priority(b.optString("name"))));return new JSONArray(selected);}
 static int priority(String name){String n=name.toLowerCase(Locale.ROOT);return n.contains("waha")||n.contains("ваха")?0:1;}
}
